const nav=document.getElementById("mainNav");window.addEventListener("scroll",()=>{nav.classList.toggle("scrolled",window.scrollY>80)});const menuBtn=document.getElementById("mobileMenuBtn"),offcanvasNav=document.getElementById("offcanvasNav"),overlay=document.getElementById("offcanvasOverlay"),closeBtn=document.getElementById("offcanvasClose");function openMenu(){menuBtn.classList.add("active"),offcanvasNav.classList.add("active"),overlay.classList.add("active"),document.body.style.overflow="hidden"}function closeMenu(){menuBtn.classList.remove("active"),offcanvasNav.classList.remove("active"),overlay.classList.remove("active"),document.body.style.overflow=""}menuBtn.addEventListener("click",openMenu),closeBtn.addEventListener("click",closeMenu),overlay.addEventListener("click",closeMenu),document.addEventListener("keydown",e=>{"Escape"===e.key&&closeMenu()}),document.querySelectorAll(".offcanvas-link").forEach(e=>{e.addEventListener("click",closeMenu)}),window.addEventListener("load",function(){const e=document.getElementById("creative-preloader");e&&(e.classList.add("preloader-fade-out"),setTimeout(()=>{e.remove()},600))}),document.addEventListener("DOMContentLoaded",function(){[...document.querySelectorAll('[data-bs-toggle="tooltip"]')].map(e=>new bootstrap.Tooltip(e))});const observer=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&(e.target.classList.add("visible"),observer.unobserve(e.target))})},{threshold:.2});document.querySelectorAll(".fade-up").forEach(e=>observer.observe(e));const counterObserver=new IntersectionObserver(e=>{e.forEach(e=>{if(!e.isIntersecting)return;const t=e.target,n=+t.dataset.target,o=n/125;let s=0;const c=setInterval(()=>{s+=o,s>=n?(t.textContent=n.toLocaleString()+"+",clearInterval(c)):t.textContent=Math.floor(s).toLocaleString()},16);counterObserver.unobserve(t)})},{threshold:.5});document.querySelectorAll(".counter-number").forEach(e=>counterObserver.observe(e));